contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 v) public payable {
        uint256 balBefore = address(c).balance;
        uint256 depBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted = true;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 balAfter = address(c).balance;
        uint256 depAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert(reverted ? balAfter == balBefore && depAfter == depBefore : balAfter == balBefore - v && depAfter == depBefore);
    }
}

