pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        uint256 balBefore = address(c).balance;
        uint256 depBefore;
        try c.depositsCount() returns (uint256 __r) { depBefore = __r; } catch { return; }
        bool reverted = true;
        try c.withdraw(v) { reverted = false; } catch { reverted = true; }
        uint256 balAfter = address(c).balance;
        uint256 depAfter;
        try c.depositsCount() returns (uint256 __r) { depAfter = __r; } catch { return; }
        assertTrue(reverted ? balAfter == balBefore && depAfter == depBefore : balAfter == balBefore - v && depAfter == depBefore);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
